namespace Trackwise.DbMigrator.Models;

/// <summary>
/// One truck's share of an nSFS parts requisition (Manila Reefer, 2025 on). Seeded by
/// <c>RepairHistorySeeder</c>; generated by <c>monday-export/scripts/nsfs_repairs.py</c>.
/// </summary>
public record RepairData
{
    public required string Plate { get; set; }

    /// <summary>The nSFS parts requisition (<c>RFV26-001517-M</c>).</summary>
    public string? RequisitionNumber { get; set; }

    public required DateOnly ServiceDate { get; set; }

    /// <summary>A <c>MaintenanceType</c> name.</summary>
    public string Type { get; set; } = "Repair";

    /// <summary>A <c>VehicleSystem</c> name, or null where it isn't clear.</summary>
    public string? System { get; set; }

    public string? Vendor { get; set; }
    public string? Invoice { get; set; }
    public required string Description { get; set; }
    public decimal LaborCost { get; set; }
    public string? Notes { get; set; }
    public RepairPartData[] Parts { get; set; } = [];
}

public record RepairPartData
{
    public required string Name { get; set; }
    public string? Description { get; set; }
    public int Quantity { get; set; } = 1;
    public decimal UnitCost { get; set; }
}

/// <summary>An active reefer's weekly PMS, with when it was last done where Monday's PMS board says.</summary>
public record ReeferPmsData
{
    public required string Plate { get; set; }
    public DateOnly? LastDoneOn { get; set; }
}
